use vstd::prelude::*;

verus! {
    // Function to determine the value at position (i, j) in the identity matrix
    spec fn diag_val(i: int, j: int) -> f64
    {
        if i == j {
            1.0
        } else {
            0.0
        }
    }

    // Function to create an n x n identity matrix
    fn identity(n: usize) -> (result: Vec<Vec<f64>>)
        requires
            n >= 0,
        ensures
            result.len() == n,
            forall |i: int| 0 <= i < n ==> result[i as usize].len() == n,
            forall |i: int, j: int| 0 <= i < n && 0 <= j < n ==> result[i as usize][j as usize] == diag_val(i, j),
    {
        let mut result: Vec<Vec<f64>> = Vec::new();
        
        // Construct the identity matrix
        let mut idx: usize = 0;
        while idx < n
            invariant
                idx <= n,
                result.len() == idx,
                forall |i: int| 0 <= i < idx ==> result[i as usize].len() == n,
                forall |i: int, j: int| 0 <= i < idx && 0 <= j < n ==> result[i as usize][j as usize] == diag_val(i, j),
            decreases n - idx,
        {
            // Create a new row
            let mut row: Vec<f64> = Vec::new();
            let mut jdx: usize = 0;
            while jdx < n
                invariant
                    jdx <= n,
                    row.len() == jdx,
                {
                    row.push(diag_val(idx as int, jdx as int));
                    jdx = jdx + 1;
                }
            result.push(row);
            idx = idx + 1;
        }
        result
    }
}

